-- =====================================================================
-- EDU — 03-demo-data.sql   (PostgreSQL; OPTIONAL — TEST/STAGING ONLY)
-- The synthetic demo data from the app's seeders @ 761c3f9, generated by
-- database/sql/generate.sh: 284 users incl. every account in TEST_ACCOUNTS.md,
-- 20 schools, 100 complaints, feedback, scores. All passwords = Password123!
-- (public, in this repo). NEVER import into a real production database.
-- Import AFTER 01 and 02, into an otherwise empty database.
-- =====================================================================

SET client_encoding = 'UTF8';
SET search_path = public;

BEGIN;























-- Move each id sequence past the explicit ids inserted above
SELECT setval(pg_get_serial_sequence('public.schools', 'id'), COALESCE((SELECT MAX(id) FROM public.schools), 1), (SELECT MAX(id) IS NOT NULL FROM public.schools));
